/**
 * hooks/useVersionCheck.js - detect a newer hub build deployed while this tab
 * stayed open, so the app can offer a reload instead of silently running stale
 * code (the root cause of "the fix didn't work until I refreshed").
 *
 * Compares BUILD_ID baked into this bundle against the deployed
 * public/version.json. Used by App.js to drive the UpdatePrompt.
 *
 * @gotcha never auto-reloads. A creator could be mid-invoice; the reload is
 *         always a deliberate user action.
 * @see docs/CODEBASE.md section 18 "Version handshake"
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { BUILD_ID } from '../version.generated';

const VERSION_URL = `${process.env.PUBLIC_URL || ''}/version.json`;
const POLL_MS = 20 * 60 * 1000; // 20 min backstop; focus is the real trigger

/** @returns {{updateAvailable: boolean, reload: () => void, dismiss: () => void}} */
export function useVersionCheck() {
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const dismissedRef = useRef(null); // build id the user chose to ignore

  const check = useCallback(async () => {
    if (typeof fetch !== 'function') return;
    try {
      const res = await fetch(`${VERSION_URL}?_=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) return;
      const data = await res.json();
      const deployed = data && data.build;
      if (!deployed || deployed === BUILD_ID) return;     // up to date
      if (deployed === dismissedRef.current) return;       // user said not now
      setUpdateAvailable(true);
    } catch {
      // Offline or transient - never nag on a failed check.
    }
  }, []);

  useEffect(() => {
    check();
    const onVisible = () => { if (document.visibilityState === 'visible') check(); };
    document.addEventListener('visibilitychange', onVisible);
    const id = setInterval(check, POLL_MS);
    return () => {
      document.removeEventListener('visibilitychange', onVisible);
      clearInterval(id);
    };
  }, [check]);

  const reload = useCallback(() => {
    // Full document reload pulls the new index.html + hashed bundle.
    window.location.reload();
  }, []);

  const dismiss = useCallback(async () => {
    // Remember the build we dismissed so we don't re-prompt for it; a still
    // newer deploy later will surface again.
    try {
      const res = await fetch(`${VERSION_URL}?_=${Date.now()}`, { cache: 'no-store' });
      if (res.ok) { const d = await res.json(); dismissedRef.current = d && d.build; }
    } catch { /* keep whatever we had */ }
    setUpdateAvailable(false);
  }, []);

  return { updateAvailable, reload, dismiss };
}
