/**
 * hooks/useModalA11y.js: the four things that make an overlay a dialog to a keyboard and to a
 * screen reader, in one place.
 *
 * Escape (delegated to `useEscapeKey`), focus moved IN on open, focus TRAPPED while open, and
 * focus RESTORED to whatever opened it. Without them an overlay is decoration: Tab walks
 * straight out into the page underneath, which is still fully readable, and closing drops
 * focus to `<body>` so the next Tab restarts at the top of the sidebar.
 *
 * Most callers get this through `components/shared/Modal.js` and should never reach for the
 * hook. It is exported for the two overlays with no `.modal-header` to label: the invoice PDF
 * shell and the avatar lightbox.
 *
 * @gotcha THE TRAP YIELDS TO THE TOPMOST OVERLAY, same rule and same reason as `useEscapeKey`:
 *         a ConfirmDialog opens over a form modal, and a trap that does not yield holds Tab in
 *         the modal underneath the dialog the user is looking at.
 * @gotcha focus is moved in ONLY when it is not already inside. React applies `autoFocus`
 *         during commit and this effect runs after it, so focusing unconditionally would steal
 *         the caret out of the field nineteen modals deliberately put it in.
 * @gotcha the restore runs in the effect CLEANUP, not in the close handler, so it covers every
 *         way a modal can leave: Escape, the X, Cancel, a successful save, or a parent that
 *         unmounts the whole panel.
 * @see components/shared/Modal.js, hooks/useEscapeKey.js, docs/DESIGN.md
 */
import { useEffect, useRef } from 'react';
import { useEscapeKey } from './useEscapeKey';

/**
 * Everything focusable inside `el`, in tab order.
 *
 * @gotcha NO VISIBILITY FILTER. The obvious `offsetParent !== null` guard is always null under
 *         jsdom, so it would empty this list in every test while passing in a browser.
 */
function focusables(el) {
  return [...el.querySelectorAll(
    'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]),'
    + ' textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
  )];
}

/**
 * @param { => void} onClose fired on Escape.
 * @param {boolean} [enabled=true] false while the overlay is not rendered.
 * @returns {{overlayRef: object, dialogRef: object}} put `overlayRef` on the
 *          `.modal-overlay` and `dialogRef` on the element carrying `role="dialog"`.
 */
export function useModalA11y(onClose, enabled = true) {
  const overlayRef = useRef(null);
  const dialogRef  = useRef(null);

  useEscapeKey(onClose, enabled, overlayRef);

  useEffect(() => {
    if (!enabled) return undefined;
    const opener = document.activeElement;
    const el = dialogRef.current;
    if (el && !el.contains(document.activeElement)) {
      (focusables(el)[0] || el).focus();
    }
    return () => {
      if (opener && typeof opener.focus === 'function' && document.contains(opener)) {
        opener.focus();
      }
    };
  }, [enabled]);

  useEffect(() => {
    if (!enabled) return undefined;
    const handler = (e) => {
      if (e.key !== 'Tab') return;
      const el = dialogRef.current;
      if (!el) return;
      const overlays = document.querySelectorAll('.modal-overlay');
      if (overlays.length && overlays[overlays.length - 1] !== overlayRef.current) return;
      const items = focusables(el);
      if (!items.length) { e.preventDefault(); el.focus(); return; }
      const first = items[0];
      const last  = items[items.length - 1];
      const active = document.activeElement;
      const outside = !el.contains(active);
      if (e.shiftKey && (outside || active === first)) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && (outside || active === last)) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [enabled]);

  return { overlayRef, dialogRef };
}
