/**
 * App.js - the hub's root: providers, top-level routing, and the global
 * idle / update overlays.
 *
 * Routing (in AppInner, after auth + MFA resolve):
 *   admin              -> AdminDashboard
 *   creator + mobile   -> MobilePostPage  (<=768px, unless "show full site")
 *   creator + desktop  -> CreatorDashboard
 * All three are lazy-loaded behind a Suspense splash.
 *
 * @gotcha the MFA intercepts (needs_totp / needs_enrollment) run BEFORE the
 *         profile check, and an AAL1 needs_totp session has no profile yet (see
 *         useAuth). A recovery link forces LoginPage regardless of session.
 * @see hooks/useAuth.js (mfaState machine), docs/CODEBASE.md (routing / auth)
 */
import React, { useEffect, useState, lazy, Suspense } from 'react';
import { AuthProvider, useAuth } from './hooks/useAuth';
import { IdleContext } from './contexts/IdleContext';
import { StatusOptionsProvider, useStatusOptions } from './contexts/StatusOptionsContext';
import { ConfirmProvider } from './components/shared/ConfirmDialog';
import { ToastProvider } from './components/shared/Toast';
import ReadError from './components/shared/ReadError';
import { useIdleTimeout } from './hooks/useIdleTimeout';
import { useVersionCheck } from './hooks/useVersionCheck';
import LoginPage from './pages/LoginPage';
import MFATOTPScreen from './components/auth/MFATOTPScreen';
import MFASetupScreen from './components/auth/MFASetupScreen';
import './App.css';

/**
 * Blocks the dashboards while the status vocabulary did not read.
 *
 * It lives here, and not in the provider, for two reasons: a context may not import a
 * component (the import zones forbid it), and there is no single screen to report this on.
 * `status_options` IS the app's status vocabulary, so a refused read is invisible on thirty
 * views at once, each rendering blank badges and empty status pickers as fact.
 * @see contexts/StatusOptionsContext.js
 */
function StatusVocabularyGate({ children }) {
  const { error, refresh } = useStatusOptions();
  if (!error) return children;
  return (
    <div className="page" style={{ maxWidth: 560, margin: '80px auto' }}>
      <ReadError error={error} onRetry={refresh} />
    </div>
  );
}

const AdminDashboard  = lazy(() => import('./pages/AdminDashboard'));
const CreatorDashboard = lazy(() => import('./pages/CreatorDashboard'));
const MobilePostPage  = lazy(() => import('./components/creator/MobilePostPage'));

/** Centered blocking modal warning of imminent idle sign-out; "Stay signed in" cancels. */
function IdleWarning({ countdown, onStayLoggedIn }) {
  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9999,
      background: 'rgba(0,0,0,0.75)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      <div style={{
        background: 'var(--surface)', border: '1px solid var(--border)',
        borderRadius: 12, padding: '36px 40px', maxWidth: 360, textAlign: 'center',
        boxShadow: 'var(--shadow-lg)',
      }}>
        <div style={{ fontSize: 13, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', marginBottom: 12 }}>
          Still there?
        </div>
        <div style={{ fontSize: 13, color: 'var(--muted)', lineHeight: 1.7, marginBottom: 24 }}>
          You&rsquo;ve been inactive for a while.<br />
          Signing out in{' '}
          <span style={{ color: 'var(--blue)', fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>
            {countdown}s
          </span>.<br />
          {/* The copy names the loss, because a half-filled invoice is a normal thing to leave
              on screen while fetching a number out of an email, and "you've been inactive" does
              not read as "your typing is about to go". */}
          Anything you have typed and not saved will be lost.
        </div>
        <button className="btn btn-primary" onClick={onStayLoggedIn} style={{ width: '100%' }}>
          Stay signed in
        </button>
      </div>
    </div>
  );
}

/**
 * Quiet, non-blocking "new version" notice (bottom-left so it clears the idle
 * modal and the user menu). Calm by design: never covers the screen, never
 * reloads on its own (a creator may be mid-invoice). @see useVersionCheck.
 */
function UpdatePrompt({ onReload, onDismiss }) {
  const reduce = typeof window !== 'undefined' && window.matchMedia
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  return (
    <div
      role="status"
      aria-live="polite"
      style={{
        position: 'fixed', left: 'max(20px, env(safe-area-inset-left))',
        bottom: 'max(20px, env(safe-area-inset-bottom))', zIndex: 900,
        width: 'min(320px, calc(100vw - 40px))',
        background: 'var(--surface)', border: '1px solid var(--border2)',
        borderRadius: 10, padding: '14px 16px',
        boxShadow: 'var(--shadow-md)',
        animation: reduce ? 'fadeIn 0.3s ease' : 'slideUp 0.42s cubic-bezier(0.22,1,0.36,1)',
      }}
    >
      <div style={{
        fontFamily: 'var(--font-display)', fontSize: 13, letterSpacing: '2.5px',
        color: 'var(--muted)', marginBottom: 6,
      }}>
        NEW VERSION
      </div>
      <div style={{ fontSize: 13, color: 'var(--white)', lineHeight: 1.55, marginBottom: 14 }}>
        A newer version of the hub is ready. Reload when you have a moment.
      </div>
      <div style={{ display: 'flex', gap: 8 }}>
        <button className="btn btn-primary btn-sm" onClick={onReload}>Reload</button>
        <button className="btn btn-ghost btn-sm" onClick={onDismiss}>Later</button>
      </div>
    </div>
  );
}

/**
 * WCAG SC 2.4.1. The sidebar renders before the content, so without this every keyboard user
 * crossed about twenty nav buttons on every view change. The target is the main landmark each
 * shell renders; it is inert on the screens that have none (login, MFA), which is correct,
 * because those have no nav to bypass.
 *
 * Visually hidden until focused, which is the only state it is meant to be seen in.
 */
function SkipLink() {
  return <a className="skip-link" href="#main-content">Skip to main content</a>;
}

/** True when the URL hash is a Supabase password-recovery link (forces LoginPage). */
function isRecoveryLink() {
  const params = new URLSearchParams(window.location.hash.substring(1));
  return params.get('type') === 'recovery' && !!params.get('access_token');
}

/** Resolves auth + MFA, then routes to the right dashboard; hosts idle + update overlays. */
function AppInner() {
  const { user, profile, loading, mfaState, signOut } = useAuth();
  const { showWarning, countdown, stayLoggedIn, secondsLeft } = useIdleTimeout({ profile, signOut });
  const { updateAvailable, reload: reloadForUpdate, dismiss: dismissUpdate } = useVersionCheck();
  const [useMobileView, setUseMobileView] = useState(() => window.matchMedia('(max-width: 768px)').matches);
  const [isRecovery] = useState(() => isRecoveryLink());

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setUseMobileView(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);
  // Tracks whether user dismissed the enrollment prompt this session
  const [enrollmentDismissed, setEnrollmentDismissed] = useState(false);

  if (loading) {
    return (
      <div className="splash">
        <div className="splash-logo">NYS<span>T</span>ERYS</div>
        <div className="splash-spinner" />
      </div>
    );
  }

  // Recovery link must always land on LoginPage regardless of current session
  if (isRecovery || !user) return <LoginPage />;

  // MFA intercepts run before the profile check - profile is not fetched at
  // AAL1 when the user has an enrolled factor (needs_totp path skips fetchProfile)
  if (mfaState === 'needs_totp') return <MFATOTPScreen />;

  // Prompt for enrollment on first login. Only a creator may skip it, and only for the
  // session: an admin at AAL1 still reads legal name, date of birth and home address,
  // because that is the one policy in the schema that does not test is_aal2(). A profile
  // that has not arrived yet gets no skip either, so the grace period is never granted by
  // a race.
  if (mfaState === 'needs_enrollment' && !enrollmentDismissed) {
    return (
      <MFASetupScreen
        onSkip={profile?.role === 'creator' ? () => setEnrollmentDismissed(true) : undefined}
        onComplete={() => setEnrollmentDismissed(true)}
      />
    );
  }

  // Profile must be loaded before rendering any dashboard
  if (!profile) return <LoginPage />;

  const splash = <div className="splash"><div className="splash-logo">NYS<span>T</span>ERYS</div><div className="splash-spinner" /></div>;

  return (
    <IdleContext.Provider value={{ secondsLeft }}>
      <SkipLink />
      <StatusOptionsProvider>
        <ToastProvider>
          <ConfirmProvider>
            <StatusVocabularyGate>
              <Suspense fallback={splash}>
                {profile.role === 'creator' && useMobileView
                  ? <MobilePostPage onShowFullSite={() => setUseMobileView(false)} />
                  : (profile.role === 'admin' ? <AdminDashboard /> : <CreatorDashboard />)
                }
              </Suspense>
            </StatusVocabularyGate>
          </ConfirmProvider>
        </ToastProvider>
      </StatusOptionsProvider>
      {showWarning && <IdleWarning countdown={countdown} onStayLoggedIn={stayLoggedIn} />}
      {updateAvailable && !showWarning && (
        <UpdatePrompt onReload={reloadForUpdate} onDismiss={dismissUpdate} />
      )}
    </IdleContext.Provider>
  );
}


/** Root component: wraps everything in AuthProvider and mounts AppInner. */
export default function App() {
  return (
    <AuthProvider>
      <AppInner />
    </AuthProvider>
  );
}
