/**
 * components/shared/Modal.js: the one home for a hub modal.
 *
 * Owns the overlay, the panel, the header and every accessibility property a dialog needs:
 * `role="dialog"`, `aria-modal`, `aria-labelledby` pointing at its own `<h2>`, Escape, the
 * focus trap and the focus restore. A call site supplies a title, a width and a body.
 *
 * @gotcha NO `onClick` ON THE OVERLAY, and never add one. Backdrop-click-to-close was removed
 *         app-wide because a mousedown inside a form that releases on the overlay fires a
 *         click there and silently discards the work. @see docs/DESIGN.md
 * @gotcha the width is a three-value SCALE, never a number. `maxWidth` was passed through
 *         verbatim while the wrapper was being adopted, deliberately, so adopting it changed
 *         no modal's size; the thirteen widths that left behind are now `SIZES` below.
 * @see hooks/useModalA11y.js
 */
import React, { createContext, useCallback, useContext, useId } from 'react';
import { useModalA11y } from '../../hooks/useModalA11y';
import { useUnsavedGuard, DISCARD_PROMPT } from '../../hooks/useUnsavedGuard';
import { useConfirm } from '../../contexts/ConfirmContext';

/** The guarded close, so a footer Cancel leaves by the same door as Escape and the X. */
const ModalCloseCtx = createContext(null);

/**
 * The three widths a modal may be, keyed by what it holds rather than by how big it is.
 *
 * Measured, not chosen: each is the width the product had already converged on for that class
 * of content, which is the rule `docs/DESIGN.md` section 2a states for the other scales. The
 * thirteen live widths were one content class wearing five sizes.
 *
 * - `sm` a DECISION: a sentence or two and two buttons. 55 to 60 characters of 13px body,
 *   which is what `ConfirmDialog` and nine others had already settled on.
 * - `md` a FORM: labelled fields, sometimes a two-column `.form-row` whose columns each need
 *   room for a date or a money input.
 * - `lg` a GRID: a table, or a form laid out in columns. The manual journal entry's five
 *   columns is the widest thing the hub puts in a dialog.
 */
const SIZES = { sm: 460, md: 560, lg: 760 };

/**
 * A modal's Cancel or Close button. Identical to a plain `.btn` except that it leaves through
 * the modal's guard, so it cannot be the one exit that discards a half-filled form in silence.
 *
 * @param {string} [props.className='btn btn-ghost']
 */
export function ModalClose({ className = 'btn btn-ghost', children, ...rest }) {
  const close = useContext(ModalCloseCtx);
  return (
    <button type="button" className={className} onClick={close} {...rest}>{children}</button>
  );
}

/**
 * @param {object} props
 * @param {React.ReactNode} props.title    the `<h2>` text; also the dialog's accessible name
 * @param {React.ReactNode} [props.subtitle] a muted line under the title
 * @param {object} [props.titleStyle]      per-site title overrides, all of them font sizes
 * @param {'sm'|'md'|'lg'} [props.size='md'] the panel's width, by what it holds. @see SIZES
 * @param { => void} props.onClose         Escape, the close button, and the focus restore
 * @param {boolean} [props.closeDisabled]  greys the close button mid-write
 * @param {boolean} [props.showClose=true] false for the two dialogs whose only exits are their
 *        own footer buttons
 * @param {string} [props.closeLabel='X']  the close button's text; a glyph gets `btn-icon`
 *        sizing and anything else gets `btn-sm`, which is the only difference between them
 * @param {boolean} [props.guard=true]  false opts out of the unsaved-changes confirm, for a
 *        dialog whose typed input IS the confirmation and which would otherwise ask about
 *        itself
 * @param {string} [props.modalClassName]  extra classes on the panel
 * @param {object} [props.modalStyle]     per-site panel overrides beside `maxWidth`
 */
export default function Modal({
  title,
  subtitle = null,
  titleStyle = undefined,
  size = 'md',
  onClose,
  closeDisabled = false,
  showClose = true,
  closeLabel = '✕',
  modalClassName = '',
  modalStyle = undefined,
  guard = true,
  children,
}) {
  const titleId = useId();
  const confirm = useConfirm();
  const { dirty, dirtyProps } = useUnsavedGuard(guard);

  const requestClose = useCallback(async () => {
    if (!dirty) { onClose(); return; }
    if (await confirm(DISCARD_PROMPT)) onClose();
  }, [confirm, dirty, onClose]);

  const { overlayRef, dialogRef } = useModalA11y(requestClose);
  const heading = (
    <h2 className="modal-title" id={titleId} style={titleStyle}>{title}</h2>
  );

  return (
    <div className="modal-overlay" ref={overlayRef}>
      <div
        ref={dialogRef}
        className={`modal${modalClassName ? ` ${modalClassName}` : ''}`}
        style={{ maxWidth: SIZES[size] || SIZES.md, ...modalStyle }}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        {...dirtyProps}
      >
        <div className="modal-header">
          {subtitle ? (
            <div>
              {heading}
              <div className="modal-subtitle">{subtitle}</div>
            </div>
          ) : heading}
          {showClose ? (
            <button
              type="button"
              className={`btn btn-ghost ${closeLabel === '✕' ? 'btn-icon' : 'btn-sm'}`}
              onClick={requestClose}
              disabled={closeDisabled}
              aria-label="Close"
            >
              {closeLabel}
            </button>
          ) : null}
        </div>
        <ModalCloseCtx.Provider value={requestClose}>{children}</ModalCloseCtx.Provider>
      </div>
    </div>
  );
}
