/**
 * contexts/StatusOptionsContext.js - the single source for workflow status
 * options and active expense (6xxx) ledger accounts.
 *
 * Fetches status_options (grouped by group_key: campaign|payment|deliverable|
 * payout|split) and the active 6xxx expense accounts once, and exposes them so
 * badge/dropdown components never hardcode status arrays.
 *
 * Used by: every status badge / status dropdown and the expense-category pickers.
 *
 * @gotcha consumers must derive their options from this context (id->value maps,
 *         memoized) rather than hardcoding status strings, or a config change in
 *         Admin will not propagate. @see CLAUDE.md StatusOptionsContext.
 * @gotcha `loading` false with an empty `options` is NOT "there are no statuses". It is what a
 *         refused read leaves behind, and it is invisible on every screen at once: thirty views
 *         derive badges, filters and form defaults from the vocabulary, so an empty one renders
 *         blank badges, `Select status...` as the only choice in every picker, and filters that
 *         compare against nothing. That is why `error` exists beside `loading`. The shell
 *         blocks on it in `App.js` (StatusVocabularyGate), which is where a component may be
 *         rendered: a context may not import one.
 */
import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';

const StatusOptionsContext = createContext(null);

/** Provides { options, expenseAccounts, error, expenseAccountsError, loading, refresh }. */
export function StatusOptionsProvider({ children }) {
  const [options, setOptions] = useState({});
  const [expenseAccounts, setExpenseAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  // Reported separately and NOT blocking: the 6xxx accounts fill the expense-category pickers
  // in two forms, so their absence is a claim inside a control rather than across the shell.
  const [expenseAccountsError, setExpenseAccountsError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    setExpenseAccountsError(null);
    const [soRes, laRes] = await Promise.all([
      supabase.from('status_options').select('*').order('group_key').order('sort_order'),
      supabase.from('ledger_accounts')
        .select('id, code, name, is_active, is_system')
        .eq('type', 'expense')
        .like('code', '6%')
        .order('code'),
    ]);
    if (soRes.error) {
      setError(soRes.error);
      setOptions({});
      setExpenseAccounts([]);
      setLoading(false);
      return;
    }
    const grouped = {};
    (soRes.data || []).forEach(r => {
      (grouped[r.group_key] = grouped[r.group_key] || []).push(r);
    });
    setOptions(grouped);
    if (laRes.error) setExpenseAccountsError(laRes.error);
    setExpenseAccounts(laRes.data || []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  return (
    <StatusOptionsContext.Provider value={{ options, expenseAccounts, error, expenseAccountsError, loading, refresh: load }}>
      {children}
    </StatusOptionsContext.Provider>
  );
}

/** Access { options, expenseAccounts, error, expenseAccountsError, loading, refresh }. */
export function useStatusOptions() {
  return useContext(StatusOptionsContext);
}
